def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 1:
        return 'C' if history[0][1] == 'C' else 'D'
    if n == 2:
        if history[-1][1] == 'D':
            return 'D'
        return 'C'

    my = [h[0] for h in history]
    opp = [h[1] for h in history]

    opp_def = sum(1 for x in opp if x == 'D')
    my_def = sum(1 for x in my if x == 'D')

    if n >= 5 and opp_def >= n * 0.6:
        return 'D'

    if n >= 95:
        tft_match = 0
        for i in range(1, n):
            if opp[i] == my[i - 1]:
                tft_match += 1
        if tft_match >= n - 3:
            if n <= 98:
                return 'C'
            else:
                return 'D'
        else:
            return 'D'

    responses_def = 0
    responses_coop = 0
    for i in range(n - 1):
        if my[i] == 'D':
            if opp[i + 1] == 'D':
                responses_def += 1
            else:
                responses_coop += 1
    total_responses = responses_def + responses_coop
    retaliation_rate = responses_def / total_responses if total_responses > 0 else 0.5
    base_defect_rate = opp_def / n if n > 0 else 0.0

    non_reactive = False
    retaliatory = False
    if total_responses > 0:
        if retaliation_rate <= base_defect_rate + 0.15:
            non_reactive = True
        if retaliation_rate > base_defect_rate + 0.25:
            retaliatory = True

    if non_reactive and my_def >= 3:
        return 'D'

    if n >= 1 and my[-1] == 'D':
        return 'C'

    if opp[-1] == 'D':
        if opp_def <= n * 0.2 and n >= 10:
            if n >= 2 and opp[-2] == 'D':
                return 'D'
            if rng.random() < 0.5:
                return 'C'
        return 'D'

    if non_reactive:
        defect_prob = 0.7
    elif retaliatory:
        defect_prob = 0.05
    else:
        if my_def == 0 and n >= 10:
            defect_prob = 0.3
        elif my_def > 0:
            defect_prob = 0.5
        else:
            defect_prob = 0.1

    if n >= 10 and rng.random() < defect_prob:
        return 'D'

    return 'C'
